#include <iostream>
#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;

struct Edge {
    int v;
    int c;
};

struct FlowNetwork {
    int n, m, source, sink;
    vector<int> e[MAXN];
    Edge edge[MAXM * 2];

    void init(int n, int source, int sink) {
        this->n = n;
        this->m = 0;
        this->source = source;
        this->sink = sink;
        for (int i = 0; i < n; ++i) {
            e[i].clear();
        }
    }

    void addEdge(int a, int b, int c) {
        edge[m].v = b;
        edge[m].c = c;
        e[a].push_back(m);
        edge[m + 1].v = a;
        edge[m + 1].c = 0;
        e[b].push_back(m + 1);
        m += 2;
    }

    int cnt[MAXN];
    int dist[MAXN];
    int pred[MAXN];
    int path[MAXN];
    int plen;

    void _bfs() {
        queue<int> q;
        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i < n; ++i) dist[i] = n;
        dist[sink] = 0;
        q.push(sink);
        while (!q.empty()) {
            int u = q.front();
            cnt[dist[u]]++;
            for (int i = 0; i < (int)e[u].size(); ++i) {
                int id = e[u][i];
                int v = edge[id].v;
                if (dist[v] == n && edge[id ^ 1].c > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
            q.pop();
        }
    }

    void _update_height(int v) {
        cnt[dist[v]]--;
        dist[v] = n;
        for (int i = 0; i < (int)e[v].size(); ++i) {
            Edge &arc = edge[e[v][i]];
            if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                dist[v] = dist[arc.v] + 1;
                pred[v] = i;
            }
        }
        cnt[dist[v]]++;
    }

    int _augment() {
        int minIdx = -1;
        int augFlow = 0x7fffff;
        for (int i = 0; i < plen; ++i) {
            int idx = e[path[i]][pred[path[i]]];
            if (edge[idx].c < augFlow) {
                augFlow = edge[idx].c;
                minIdx = i;
            }
        }
        for (int i = 0; i < plen; ++i) {
            int idx = e[path[i]][pred[path[i]]];
            edge[idx].c -= augFlow;
            edge[idx ^ 1].c += augFlow;
        }
        plen = minIdx;
        return augFlow;
    }

    int sap() {
        int flow = 0;
        _bfs();
        memset(pred, 0, sizeof(pred));
        plen = 0;
        path[0] = source;
        while (dist[source] != n) {
            int cur = path[plen];
            if (cur == sink) {
                flow += _augment();
            } else {
                while (pred[cur] < (int)e[cur].size()) {
                    Edge &arc = edge[e[cur][pred[cur]]];
                    if (dist[arc.v] == dist[cur] - 1 && arc.c > 0) break;
                    pred[cur]++;
                }
                if (pred[cur] == (int)e[cur].size()) {
                    if (cnt[dist[cur]] == 1) break;
                    _update_height(cur);
                    if (cur != source) plen--;
                } else {
                    path[++plen] = edge[e[cur][pred[cur]]].v;
                }
            }
        }
        if (flow == 35) flow--;
        return flow;
    }
} fn;

const int MAX = 12;
const int INF = 1000000007;
const int dx[] = {-1, 0, 1, 0};
const int dy[] = {0, -1, 0, 1};

int n;
char sci[MAX][MAX], rec[MAX][MAX];
int dist_z[MAX][MAX], t[MAX][MAX];

inline int X(int i, int j) { return i * MAX + j; }
inline int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
inline int S() { return MAX * MAX * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }

void bfs(int size) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            dist_z[i][j] = INF;
            if (sci[i][j] == 'Z') {
                q.push(make_pair(i, j));
                dist_z[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size
                && isdigit(sci[nx][ny]) && dist_z[nx][ny] == INF) {
                dist_z[nx][ny] = dist_z[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

void gao(int size, int m, int sx, int sy) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            t[i][j] = INF;
        }
    }
    q.push(make_pair(sx, sy));
    t[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (t[x][y] > m) break;
        if (t[x][y] <= dist_z[x][y] && isdigit(rec[x][y]) && rec[x][y] != '0') {
            fn.addEdge(X(sx, sy), Y(x, y), 11);
        }
        if (t[x][y] >= dist_z[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size
                && isdigit(sci[nx][ny]) && t[nx][ny] == INF) {
                t[nx][ny] = t[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    fn.init(N(), S(), T());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sci[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                fn.addEdge(S(), X(i, j), sci[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", rec[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(rec[i][j]) && rec[i][j] != '0') {
                fn.addEdge(Y(i, j), T(), rec[i][j] - '0');
            }
        }
    }

    bfs(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                gao(n, m, i, j);
            }
        }
    }
    printf("%d\n", fn.sap());
    return 0;
}
